 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':1280,'height':1000});ctx.add_init_script('window.__guest=true');ctx.route('https://www.gstatic.com/firebasejs/**',mcq_sdk);page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.route('**/api/staff-access',lambda route:mcq_api(page,route));page.goto('http://127.0.0.1:8000/cbse-mission.html#tab=mcq');entry=page.locator('.mcq-entry-form');entry.wait_for();entry.locator('[name=mcq-entry-staff]').select_option('X:one');assert entry.locator('[name=mcq-entry-class]').input_value()=='X';entry.locator('[name=mcq-entry-subject]').select_option('english');entry.get_by_role('button',name='Contribute a question',exact=False).click();form=page.locator('.mcq-single-form');assert form.locator('[name=mcq-staff]').get_attribute('type')=='hidden';assert form.locator('[name=mcq-staff]').input_value()=='X:one';assert form.locator('[name=mcq-subject]').input_value()=='english';assert form.locator('[name=mcq-correct] option').all_text_contents()==['Select','A','B','C','D'];assert form.get_by_role('radio').count()==0;form.locator('[name=mcq-notepad]').fill('Ready question\nA) One B) Two C) Three D) Four');form.locator('[name=mcq-correct]').select_option('B');form.locator('[name=mcq-pin]').fill('123');form.get_by_role('button',name='Save question with PIN',exact=True).click();form.get_by_role('status').filter(has_text='Saved QE001').wait_for();page.get_by_role('button',name='Change name / class / subject',exact=True).click();entry.wait_for();entry.locator('[name=mcq-entry-staff]').select_option('X:two');entry.locator('[name=mcq-entry-class]').select_option('X');entry.locator('[name=mcq-entry-subject]').select_option('english');entry.get_by_role('button',name='Prepare QP',exact=False).click();page.locator('[name=mcq-select-QE001]').check();auth=page.locator('.mcq-paper-form');assert auth.locator('[name=mcq-staff]').get_attribute('type')=='hidden';assert auth.locator('[name=mcq-staff]').input_value()=='X:two';auth.locator('[name=mcq-pin]').fill('456');auth.get_by_role('button',name='Generate paper',exact=True).click();page.get_by_text('Created QPE001',exact=False).wait_for();page.get_by_role('button',name='Change name / class / subject',exact=True).click();entry.get_by_role('button',name='Evaluation',exact=False).click();page.get_by_role('heading',name='Evaluate a paper',exact=True).wait_for();assert not root['mcq'].get('evaluations')
 # A whole-page photo contains the real QR at the top and the marked response strip at the bottom.
 photo=page.evaluate("""async()=>{const {loadMCQScript,bubblePoint}=await import('./cbse-mcq-scan.js');const {answerStripSVG}=await import('./cbse-mcq-print.js');await loadMCQScript('qrcode.js');const code=qrcode(0,'M');code.addData('VOA|MCQ|QPE001');code.make();async function image(svg){const img=new Image();img.src='data:image/svg+xml;base64,'+btoa(svg);await img.decode();return img;}const qr=await image(code.createSvgTag({cellSize:3,margin:12}));const strip=await image(new XMLSerializer().serializeToString(answerStripSVG(1)));const c=document.createElement('canvas');c.width=1200;c.height=1700;const g=c.getContext('2d');g.fillStyle='white';g.fillRect(0,0,c.width,c.height);g.fillStyle='black';g.font='22px Arial';g.fillText('QPE001 · English question paper',30,80);g.drawImage(qr,1030,30,130,130);g.drawImage(strip,0,1160,1200,504);const point=bubblePoint(0,1);g.beginPath();g.arc(point.x*1.2,1160+point.y*1.2,10,0,Math.PI*2);g.fill();return c.toDataURL('image/jpeg',.9).split(',')[1];}""")
 page.locator('[name=mcq-evaluation-upload]').set_input_files({'name':'marked-answer-sheet.jpg','mimeType':'image/jpeg','buffer':base64.b64decode(photo)});page.get_by_role('status').filter(has_text='answers read').wait_for();evaluation=page.locator('.mcq-evaluation-form');assert page.locator('[name=mcq-test-id]').input_value()=='QPE001';assert evaluation.locator('[name=mcq-response-0]').input_value()=='B';assert not evaluation.locator('[name=mcq-responses-reviewed]').is_checked();assert evaluation.locator('[name=mcq-staff]').input_value()=='X:two';assert page.get_by_role('dialog').count()==0;assert not root['mcq'].get('evaluations');evaluation.locator('[name=mcq-student]').select_option('X:a:one');evaluation.locator('[name=mcq-responses-reviewed]').check();evaluation.locator('[name=mcq-pin]').fill('456');evaluation.get_by_role('button',name='Save score with PIN',exact=True).click();evaluation.get_by_text('Saved 1 / 1',exact=False).wait_for();assert root['mission']['marks']['QPE001_X_a_one']['score']==1;assert root['mcq']['evaluations']['QPE001_X_a_one']['method']=='photo-assisted';page.get_by_role('button',name='Change name / class / subject',exact=True).click();entry.wait_for()
